using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> => Type={personInfo.Type.Name}, Properties={personInfo.Properties.Count}");

string json = JsonSerializer.Serialize(new Person("Ada", 39), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---
// With the default reflection resolver, any type can be resolved:
if (options.TryGetTypeInfo<Person>(out var info))
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded: {info!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Person> failed");

// With a restricted source-gen resolver, unregistered types return false:
var restricted = new JsonSerializerOptions
{
    TypeInfoResolver = PersonContext.Default
};

if (restricted.TryGetTypeInfo<Person>(out var found))
    Console.WriteLine($"TryGetTypeInfo<Person> on restricted options succeeded: {found!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Person> on restricted options: not available");

// int is NOT in PersonContext, so this should return false — no exception:
if (restricted.TryGetTypeInfo<int>(out _))
    Console.WriteLine("TryGetTypeInfo<int> on restricted options succeeded (unexpected)");
else
    Console.WriteLine("TryGetTypeInfo<int> on restricted options: not available (expected)");

// --- Types ---
public record Person(string Name, int Age);

[JsonSerializable(typeof(Person))]
public partial class PersonContext : JsonSerializerContext;

